# AUTO-GENERATED BY THE PIPELINE. Do not edit or delete: it is rewritten on every pass.
#
# start.sh and the app's startup build the database with `alembic upgrade head`
# and then run the seed. The rest of this suite builds its tables with
# `create_all()` and seeds what each test needs, so a seed that crashes on the real
# schema - a CHECK constraint its rows break, a NOT NULL column it leaves empty, a
# unique key it inserts twice - passes every other test and stops the app from
# starting. These tests run the seed the way the launchers do: on an EMPTY SQLite
# database the migrations just built, then a second time on the same database.
#
# If one fails, fix the SEED (or the model, when the constraint itself is wrong),
# not this file: give every row values the constraints accept, fill every NOT NULL
# column, and look a row up before inserting it so a second run inserts nothing.
import configparser
import os
import subprocess
import sys
from pathlib import Path

import pytest

_BACKEND = Path(__file__).resolve().parent.parent
_SKIP_PARTS = {".venv", "venv", "tests", "test", "alembic", "migrations", "node_modules", "__pycache__"}
_CANDIDATES = (
    "app/seed.py", "app/seeds.py", "app/seed_data.py", "app/db/seed.py", "app/database/seed.py",
    "app/scripts/seed.py", "seed.py", "seeds.py", "scripts/seed.py",
)
_MIGRATE = """
import sys
from alembic import command
from alembic.config import Config
cfg = Config("alembic.ini")
cfg.set_main_option("sqlalchemy.url", sys.argv[1].replace("%", "%%"))
command.upgrade(cfg, "head")
"""
# Runs the seed module as the launchers would: its __main__ block when it has one,
# else the first seed function it defines that takes nothing, or only a session.
_SEED = """
import asyncio, importlib, inspect, os, runpy, sys
module, path, url = sys.argv[1], sys.argv[2], sys.argv[3]
sys.path.insert(0, os.getcwd())
source = open(path, encoding="utf-8", errors="replace").read()
if "__name__" in source and "__main__" in source:
    runpy.run_module(module, run_name="__main__", alter_sys=True)
    sys.exit(0)
mod = importlib.import_module(module)
for name in ("main", "seed", "seed_all", "seed_data", "seed_database", "seed_db", "run_seed", "run"):
    fn = getattr(mod, name, None)
    if not callable(fn) or getattr(fn, "__module__", None) != mod.__name__:
        continue
    required = [
        p for p in inspect.signature(fn).parameters.values()
        if p.default is p.empty and p.kind in (p.POSITIONAL_ONLY, p.POSITIONAL_OR_KEYWORD)
    ]
    if not required:
        result = fn()
        if inspect.iscoroutine(result):
            asyncio.run(result)
        sys.exit(0)
    if len(required) == 1 and required[0].name in ("db", "session", "db_session", "sess", "s"):
        if inspect.iscoroutinefunction(fn):
            continue
        from sqlalchemy import create_engine
        from sqlalchemy.orm import Session
        engine = create_engine(url.replace("+aiosqlite", ""))
        with Session(engine) as session:
            fn(session)
            session.commit()
        sys.exit(0)
print("NO_SEED_ENTRY_POINT")
sys.exit(3)
"""


def _seed_module():
    found = [_BACKEND / c for c in _CANDIDATES if (_BACKEND / c).is_file()]
    if not found:
        found = sorted(
            p for p in _BACKEND.rglob("seed*.py")
            if not _SKIP_PARTS.intersection(p.relative_to(_BACKEND).parts)
        )
    if not found:
        return None
    rel = found[0].relative_to(_BACKEND).with_suffix("")
    return ".".join(rel.parts), found[0]


def _env(url):
    env = dict(os.environ)
    for name in ("dev.env", ".env.example"):
        path = _BACKEND / name
        if path.is_file():
            for line in path.read_text(encoding="utf-8", errors="replace").splitlines():
                line = line.strip()
                if line and not line.startswith("#") and "=" in line:
                    key, value = line.removeprefix("export ").split("=", 1)
                    env.setdefault(key.strip(), value.strip().strip("'").strip('"'))
            break
    env["DATABASE_URL"] = url
    # Seeds print status marks (a check mark, a cross): a console that cannot encode
    # them would crash a seed that works.
    env["PYTHONIOENCODING"] = "utf-8"
    env["PYTHONUTF8"] = "1"
    return env


def _is_async():
    parser = configparser.ConfigParser(interpolation=None)
    try:
        parser.read(_BACKEND / "alembic.ini", encoding="utf-8")
        location = parser.get("alembic", "script_location", fallback="alembic")
    except (configparser.Error, OSError):
        location = "alembic"
    env_py = Path(location.replace("%(here)s", str(_BACKEND)))
    if not env_py.is_absolute():
        env_py = _BACKEND / env_py
    try:
        text = (env_py / "env.py").read_text(encoding="utf-8", errors="replace")
    except OSError:
        return False
    return any(m in text for m in ("async_engine_from_config", "create_async_engine", "AsyncEngine"))


def _run(code, *args, env):
    proc = subprocess.run(
        [sys.executable, "-c", code, *args],
        cwd=_BACKEND, env=env, capture_output=True, text=True, encoding="utf-8", errors="replace", timeout=300,
    )
    return proc.returncode, ((proc.stdout or "") + (proc.stderr or ""))[-6000:]


@pytest.fixture(scope="module")
def seeded(tmp_path_factory):
    found = _seed_module()
    if found is None:
        pytest.skip("this backend has no seed module yet")
    module, path = found
    db = tmp_path_factory.mktemp("seed_runs") / "app.db"
    url = ("sqlite+aiosqlite:///" if _is_async() else "sqlite:///") + db.as_posix()
    env = _env(url)
    code, output = _run(_MIGRATE, url, env=env)
    if code != 0:
        pytest.skip("the migrations do not build an empty database; test_pipeline_migration_parity.py reports it")
    first = _run(_SEED, module, str(path), url, env=env)
    if first[0] == 3 and "NO_SEED_ENTRY_POINT" in first[1]:
        pytest.skip(module + " has no __main__ block and no seed function the pipeline can call")
    second = _run(_SEED, module, str(path), url, env=env) if first[0] == 0 else None
    return module, first, second


def test_the_seed_runs_on_a_freshly_migrated_database(seeded):
    module, (code, output), _second = seeded
    assert code == 0, (
        "The seed (" + module + ") crashes on the database `alembic upgrade head` builds, so the "
        "app's launchers - start.sh, the preview, the Playwright web server - cannot start it. "
        "Fix the rows it inserts (CHECK constraints, NOT NULL columns, foreign keys, unique keys) "
        "or the model when the constraint is wrong. What it printed last:" + chr(10) + output
    )


def test_the_seed_runs_a_second_time(seeded):
    module, (code, _output), second = seeded
    if code != 0:
        pytest.skip("the first run already fails")
    code, output = second
    assert code == 0, (
        "The seed (" + module + ") works once and crashes the second time. start.sh and the app's "
        "startup both run it, so every restart fails. Look a row up before inserting it. What it "
        "printed last:" + chr(10) + output
    )
